-- Saudi Arabia milestones (Stage 4 deep-dive/tracker migration)
-- 4 total, matching the static page's 4 timeline rcards.
-- 2 deep-dive-only (Phase 1 generation begins, Phase 2 Wave 1 begins) + 2
-- tracker-matched (sa-wave23, sa-wave24), both exact date/topic matches -- tracker
-- phrasing wins. Neither tracker entry sets anchor:true, so both keep anchor=0.

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sa-phase1', id, '2021-12-04', 0, NULL FROM countries WHERE name_en = 'Saudi Arabia';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sa-phase1', 'en', 'Phase 1 (Generation Phase) begins', 'All VAT-registered taxpayers must generate e-invoices using a compliant electronic system and store them digitally — no live integration with ZATCA required yet at this stage.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sa-phase2-wave1', id, '2023-01-01', 0, NULL FROM countries WHERE name_en = 'Saudi Arabia';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sa-phase2-wave1', 'en', 'Phase 2 (Integration Phase) begins — Wave 1', 'The largest taxpayers (annual revenue above SAR 3 billion) must directly integrate their billing systems with ZATCA''s Fatoora platform. Every subsequent wave brings smaller businesses into scope, each notified at least 6 months in advance.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sa-wave23', id, '2026-03-31', 0, 'https://zatca.gov.sa' FROM countries WHERE name_en = 'Saudi Arabia';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sa-wave23', 'en', 'ZATCA Fatoora — Wave 23 (turnover > SAR 750,000)', 'Businesses with VAT-taxable turnover above SAR 750,000 in 2022, 2023 or 2024 were required to complete Phase 2 integration with the Fatoora platform for real-time clearance.', '["Confirm ZATCA''s direct notification and integration deadline for your entity", "Integrate your invoicing system with the Fatoora API for real-time B2B/B2G clearance", "Ensure invoices carry a UUID, QR code and cryptographic stamp"]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'sa-wave24', id, '2026-06-30', 0, 'https://zatca.gov.sa' FROM countries WHERE name_en = 'Saudi Arabia';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sa-wave24', 'en', 'ZATCA Fatoora — Wave 24 (turnover > SAR 375,000)', 'The threshold dropped to SAR 375,000 — effectively matching the mandatory VAT-registration threshold, bringing nearly every VAT-registered business into Phase 2 clearance.', '["Assume you are in scope if VAT-registered; ZATCA notifies affected taxpayers roughly six months ahead", "Issue Standard invoices (clearance, input-VAT claimable) for B2B/B2G and Simplified invoices for B2C, reported within 24 hours"]');
